<script lang="ts">
import type { Snippet } from 'svelte';
import { untrack, tick, onMount, onDestroy } from 'svelte';
import type { HelpPanelContract } from '@unofficial-krds/contracts';
import { owned, control, resetField, ignoredKey } from './catalog-state.svelte.js';
let p: HelpPanelContract & { openerId?:string; hideOpener?:boolean; hideTopicTriggers?:boolean } = $props();
import PanelShell from './PanelShell.svelte';import {restoreFocus} from './modal-state.js';let narrow=$state(untrack(()=>typeof matchMedia==='function'&&matchMedia('(max-width:767px)').matches));let initiating=$state<HTMLElement>();const open=control(()=>p.open,untrack(()=>p.defaultOpen),untrack(()=>!narrow),open=>p.onOpenChange?.({open}));const topic=control<string|null>(()=>p.selectedTopicId,untrack(()=>p.defaultSelectedTopicId),null,id=>p.onTopicChange?.({id}));const uid=$props.id();const openerId=$derived(p.openerId??`${uid}-opener`);onMount(()=>{const media=matchMedia('(max-width:767px)');const change=()=>narrow=media.matches;change();media.addEventListener('change',change);return()=>media.removeEventListener('change',change);});async function select(id:string,event:MouseEvent){initiating=event.currentTarget as HTMLElement;const alreadyOpen=open.value;topic.request(id);if(!alreadyOpen)open.request(true);await tick();if(alreadyOpen&&open.value&&topic.value===id){const shell=document.querySelector<HTMLElement>(`[data-panel-id="${uid}"]`)?.parentElement;shell?.focus();}}
</script>
{#if !p.hideOpener}<button id={openerId} type="button" {...owned('help-panel','opener',open.value?'open':'closed')} aria-expanded={open.value} onclick={event=>{initiating=event.currentTarget;open.request(true);}}>도움말 열기</button>{/if}{#if !p.hideTopicTriggers}{#each p.topics as item(item.id)}<button type="button" {...owned('help-panel','topic-trigger',topic.value===item.id&&'active-topic')} onclick={event=>select(item.id,event)}>{item.title} 도움말</button>{/each}{/if}<PanelShell componentId="help-panel" states={[open.value?'open':'closed',topic.value&&'active-topic',narrow&&'modal'].filter(Boolean).join(' ')} open={open.value} {narrow} title="도움말" returnFocusId={p.hideOpener?undefined:openerId} fallbackFocusId={p.fallbackFocusId} initiatingElement={initiating} onClose={()=>open.request(false)}><section data-panel-id={uid}><h2>도움말</h2><button type="button" {...owned('help-panel','close')} onclick={()=>open.request(false)}>도움말 닫기</button><ul>{#each p.topics as item(item.id)}<li><button type="button" {...owned('help-panel','topic-trigger',topic.value===item.id&&'active-topic')} onclick={event=>select(item.id,event)}>{item.title}</button></li>{/each}</ul>{#each p.topics.filter(x=>x.id===topic.value) as item}<section {...owned('help-panel','body','active-topic')}><h3>{item.title}</h3><p>{item.content}</p><nav aria-label="관련 도움말" {...owned('help-panel','related','active-topic')}>{#each item.relatedLinks as link}<a href={link.href}>{link.label}</a>{/each}</nav><button type="button" onclick={()=>topic.request(null)}>목록으로</button></section>{/each}</section></PanelShell>
